contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(minAfter == minBefore);
    }

    receive() external payable {}
}

